@Service
public class OrderProcessingService {

    private final PaymentGateway paymentGateway;
    private final InventoryService inventoryService;
    private int defaultTimeoutSeconds = 30; // Mutable optional dependency via setter

    // Preferred: Constructor injection for mandatory, immutable dependencies
    public OrderProcessingService(PaymentGateway paymentGateway, InventoryService inventoryService) {
        this.paymentGateway = paymentGateway;
        this.inventoryService = inventoryService;
    }

    // Acceptable: Setter injection strictly for optional configuration properties
    @Autowired(required = false)
    public void setDefaultTimeoutSeconds(int defaultTimeoutSeconds) {
        this.defaultTimeoutSeconds = defaultTimeoutSeconds;
    }
}
